package main

import (
	"bufio"
	"crypto/tls"
	"fmt"
	"io"
	"net"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"
)

const (
	MaxHeaderSize  = 8192
	MaxBodySize    = 1048576
	BackendAddr    = "127.0.0.1:8081"
	ListenAddr     = ":8443"
	IdleTimeout    = 30 * time.Second
	MaxConnections = 1000
)

type ConnPool struct {
	mu    sync.Mutex
	conns []net.Conn
	max   int
}

func NewConnPool(max int) *ConnPool {
	return &ConnPool{max: max, conns: make([]net.Conn, 0, max)}
}

func (p *ConnPool) Get() (net.Conn, error) {
	p.mu.Lock()
	if len(p.conns) > 0 {
		c := p.conns[len(p.conns)-1]
		p.conns = p.conns[:len(p.conns)-1]
		p.mu.Unlock()
		return c, nil
	}
	p.mu.Unlock()
	return net.DialTimeout("tcp", BackendAddr, 5*time.Second)
}

func (p *ConnPool) Put(c net.Conn) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if len(p.conns) < p.max {
		p.conns = append(p.conns, c)
	} else {
		c.Close()
	}
}

var pool = NewConnPool(50)

// containsCTLChars reports whether s contains any ASCII control character
// (including CR/LF). Used to prevent header/request-line injection.
func containsCTLChars(s string) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < 0x20 || c == 0x7f {
			return true
		}
	}
	return false
}

// parseContentLength extracts Content-Length from headers, handling edge cases
func parseContentLength(headers map[string]string) (int64, error) {
	cl, ok := headers["content-length"]
	if !ok {
		return -1, nil
	}
	cl = strings.TrimSpace(cl)
	// Handle multiple Content-Length values (comma-separated per RFC 7230 Section 3.3.2)
	parts := strings.Split(cl, ",")
	var val int64 = -1
	for _, part := range parts {
		part = strings.TrimSpace(part)
		v, err := strconv.ParseInt(part, 10, 64)
		if err != nil || v < 0 {
			return -1, fmt.Errorf("invalid content-length: %s", cl)
		}
		if val == -1 {
			val = v
		} else if val != v {
			return -1, fmt.Errorf("conflicting content-length values")
		}
	}
	return val, nil
}

// determineBodyLength decides how to read the request body
// Returns: length to read (-1 for chunked, 0 for no body, >0 for fixed)
func determineBodyLength(method string, headers map[string]string) (int64, bool, error) {
	// Check Transfer-Encoding first (takes precedence per RFC 7230)
	te, hasTE := headers["transfer-encoding"]
	_, hasCL := headers["content-length"]

	// RFC 7230 Section 3.3.3: If both TE and CL are present, reject the message
	if hasTE && hasCL {
		return 0, false, fmt.Errorf("request has both Transfer-Encoding and Content-Length")
	}

	if hasTE {
		// Parse transfer-encoding, check if chunked is the final encoding
		encodings := strings.Split(strings.ToLower(te), ",")
		lastEnc := strings.TrimSpace(encodings[len(encodings)-1])
		if lastEnc != "chunked" {
			return 0, false, fmt.Errorf("final transfer-encoding must be chunked")
		}
		return -1, true, nil // chunked transfer
	}

	if hasCL {
		length, err := parseContentLength(headers)
		if err != nil || length < 0 {
			return 0, false, fmt.Errorf("invalid content-length")
		}
		if length > MaxBodySize {
			return 0, false, fmt.Errorf("body too large")
		}
		return length, false, nil
	}

	// No body indicators for safe methods
	if method == "GET" || method == "HEAD" || method == "DELETE" {
		return 0, false, nil
	}

	return 0, false, nil
}

// sanitizeHeaders removes hop-by-hop headers and normalizes
func sanitizeHeaders(headers map[string]string) map[string]string {
	hopByHop := map[string]bool{
		"connection":          true,
		"keep-alive":          true,
		"proxy-authenticate":  true,
		"proxy-authorization": true,
		"te":                  true,
		"trailer":             true,
		"transfer-encoding":   true,
		"upgrade":             true,
	}

	result := make(map[string]string)
	for k, v := range headers {
		if !hopByHop[strings.ToLower(k)] {
			result[k] = v
		}
	}
	return result
}

// readChunkedBody reads a chunked transfer-encoded body
func readChunkedBody(reader *bufio.Reader) ([]byte, error) {
	var body []byte
	for {
		// Read chunk size line
		line, err := reader.ReadString('\n')
		if err != nil {
			return nil, err
		}
		line = strings.TrimRight(line, "\r\n")

		// Parse chunk size (ignore extensions after semicolon)
		sizeStr := strings.Split(line, ";")[0]
		sizeStr = strings.TrimSpace(sizeStr)

		size, err := strconv.ParseInt(sizeStr, 16, 64)
		if err != nil {
			return nil, fmt.Errorf("invalid chunk size: %s", sizeStr)
		}

		if size == 0 {
			// Read trailing CRLF after last chunk
			reader.ReadString('\n')
			break
		}

		if size < 0 || int64(len(body))+size > int64(MaxBodySize) {
			return nil, fmt.Errorf("chunk too large")
		}

		chunk := make([]byte, size)
		_, err = io.ReadFull(reader, chunk)
		if err != nil {
			return nil, err
		}
		body = append(body, chunk...)

		// Read CRLF after chunk data
		crlf := make([]byte, 2)
		_, err = io.ReadFull(reader, crlf)
		if err != nil {
			return nil, err
		}
		if crlf[0] != '\r' || crlf[1] != '\n' {
			return nil, fmt.Errorf("missing CRLF after chunk")
		}
	}
	return body, nil
}

// parseRequest reads and parses an HTTP request from the connection
func parseRequest(reader *bufio.Reader) (string, string, string, map[string]string, []byte, error) {
	// Read request line
	reqLine, err := reader.ReadString('\n')
	if err != nil {
		return "", "", "", nil, nil, err
	}
	reqLine = strings.TrimRight(reqLine, "\r\n")
	parts := strings.SplitN(reqLine, " ", 3)
	if len(parts) != 3 {
		return "", "", "", nil, nil, fmt.Errorf("malformed request line")
	}
	method, path, version := parts[0], parts[1], parts[2]

	if version != "HTTP/1.0" && version != "HTTP/1.1" {
		return "", "", "", nil, nil, fmt.Errorf("unsupported HTTP version")
	}

	// Reject control characters in the request target to prevent request-line injection
	if path == "" || containsCTLChars(path) {
		return "", "", "", nil, nil, fmt.Errorf("invalid request target")
	}

	// Validate method
	validMethods := map[string]bool{"GET": true, "POST": true, "PUT": true, "DELETE": true, "HEAD": true, "PATCH": true, "OPTIONS": true}
	if !validMethods[method] {
		return "", "", "", nil, nil, fmt.Errorf("unsupported method")
	}

	// Read headers
	headers := make(map[string]string)
	totalHeaderSize := 0
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			return "", "", "", nil, nil, err
		}
		line = strings.TrimRight(line, "\r\n")
		if line == "" {
			break
		}
		totalHeaderSize += len(line)
		if totalHeaderSize > MaxHeaderSize {
			return "", "", "", nil, nil, fmt.Errorf("headers too large")
		}

		colonIdx := strings.IndexByte(line, ':')
		if colonIdx < 0 {
			return "", "", "", nil, nil, fmt.Errorf("malformed header line")
		}
		key := strings.ToLower(strings.TrimSpace(line[:colonIdx]))
		value := strings.TrimSpace(line[colonIdx+1:])

		// Reject control characters in header names/values to prevent header injection
		if key == "" || containsCTLChars(key) || containsCTLChars(value) {
			return "", "", "", nil, nil, fmt.Errorf("invalid header")
		}

		// For duplicate headers, append with comma (RFC 7230)
		if existing, ok := headers[key]; ok {
			headers[key] = existing + ", " + value
		} else {
			headers[key] = value
		}
	}

	// Determine body handling
	bodyLen, isChunked, err := determineBodyLength(method, headers)
	if err != nil {
		return "", "", "", nil, nil, err
	}

	var body []byte
	if isChunked {
		body, err = readChunkedBody(reader)
		if err != nil {
			return "", "", "", nil, nil, err
		}
	} else if bodyLen > 0 {
		body = make([]byte, bodyLen)
		_, err = io.ReadFull(reader, body)
		if err != nil {
			return "", "", "", nil, nil, err
		}
	}

	return method, path, version, headers, body, nil
}

// buildBackendRequest constructs the request to send to backend
func buildBackendRequest(method, path string, headers map[string]string, body []byte) []byte {
	clean := sanitizeHeaders(headers)

	var buf strings.Builder
	buf.WriteString(fmt.Sprintf("%s %s HTTP/1.1\r\n", method, path))
	buf.WriteString(fmt.Sprintf("Host: %s\r\n", BackendAddr))

	if len(body) > 0 {
		clean["content-length"] = strconv.Itoa(len(body))
	} else {
		delete(clean, "content-length")
	}

	for k, v := range clean {
		if k == "host" {
			continue
		}
		// Defensive: never forward header names/values containing control chars
		if containsCTLChars(k) || containsCTLChars(v) {
			continue
		}
		buf.WriteString(fmt.Sprintf("%s: %s\r\n", k, v))
	}
	buf.WriteString("\r\n")

	req := []byte(buf.String())
	if len(body) > 0 {
		req = append(req, body...)
	}
	return req
}

func handleConnection(conn net.Conn) {
	defer conn.Close()
	reader := bufio.NewReaderSize(conn, 4096)

	for {
		conn.SetReadDeadline(time.Now().Add(IdleTimeout))

		method, path, _, headers, body, err := parseRequest(reader)
		if err != nil {
			return
		}

		// Forward to backend
		backendReq := buildBackendRequest(method, path, headers, body)

		backendConn, err := pool.Get()
		if err != nil {
			conn.Write([]byte("HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\n\r\n"))
			return
		}

		backendConn.SetWriteDeadline(time.Now().Add(5 * time.Second))
		_, err = backendConn.Write(backendReq)
		if err != nil {
			backendConn.Close()
			conn.Write([]byte("HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\n\r\n"))
			return
		}

		// Read backend response and forward
		backendConn.SetReadDeadline(time.Now().Add(10 * time.Second))
		respReader := bufio.NewReader(backendConn)
		resp, err := http.ReadResponse(respReader, nil)
		if err != nil {
			backendConn.Close()
			conn.Write([]byte("HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\n\r\n"))
			return
		}

		// Write response back to client
		var respBuf strings.Builder
		respBuf.WriteString(fmt.Sprintf("HTTP/1.1 %d %s\r\n", resp.StatusCode, resp.Status))
		for k, vals := range resp.Header {
			for _, v := range vals {
				respBuf.WriteString(fmt.Sprintf("%s: %s\r\n", k, v))
			}
		}
		respBuf.WriteString("\r\n")
		conn.Write([]byte(respBuf.String()))

		if resp.Body != nil {
			io.Copy(conn, resp.Body)
			resp.Body.Close()
		}

		pool.Put(backendConn)
	}
}

func main() {
	cert, err := tls.LoadX509KeyPair("server.crt", "server.key")
	if err != nil {
		panic(err)
	}

	tlsConfig := &tls.Config{
		Certificates: []tls.Certificate{cert},
		MinVersion:   tls.VersionTLS12,
	}

	listener, err := tls.Listen("tcp", ListenAddr, tlsConfig)
	if err != nil {
		panic(err)
	}
	defer listener.Close()

	sem := make(chan struct{}, MaxConnections)

	for {
		conn, err := listener.Accept()
		if err != nil {
			continue
		}
		select {
		case sem <- struct{}{}:
			go func() {
				defer func() { <-sem }()
				handleConnection(conn)
			}()
		default:
			conn.Close()
		}
	}
}
